   109→/// Analyze a statically linked binary
   110→fn analyze_static(args: &Args, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   111→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   112→
   113→    // Collect all function symbols
   114→    for sym in &elf.syms {
   115→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   116→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   117→
   118→            // Skip if filtering and doesn't match
   119→            if let Some(ref filter) = args.filter {
   120→                if !name.contains(filter) {
   121→                    continue;
   122→                }
   123→            }
   124→
   125→            // Skip internal rust/compiler symbols unless --all
   126→            if !args.all && is_internal_symbol(name) {
   127→                continue;
   128→            }
   129→
   130→            functions.insert(sym.st_value, FunctionInfo {
   131→                name: name.to_string(),
   132→                size: sym.st_size,
   133→                address: sym.st_value,
   134→                references: 0,
   135→                source: Some("local".to_string()),
   136→            });
   137→        }
   138→    }
   139→
   140→    // Count references by disassembling
   141→    count_references(args, elf, binary_data, &mut functions)?;
   142→
   143→    // Convert to sorted vec
   144→    let mut func_vec: Vec<_> = functions.into_values().collect();
   145→    filter_and_sort(&args, &mut func_vec);
   146→
   147→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   148→
   149→    Ok(AnalysisResult {
   150→        binary_path: args.binary.display().to_string(),
   151→        is_dynamic: false,
   152→        total_functions: func_vec.len(),
   153→        total_code_size,
   154→        functions: func_vec,
   155→    })
   156→}
   157→
   158→/// Analyze a dynamically linked binary
   159→fn analyze_dynamic(args: &Args, elf: &Elf, binary_data: &[u8]) -> Result<AnalysisResult> {
   160→    let mut functions: HashMap<u64, FunctionInfo> = HashMap::new();
   161→
   162→    // For dynamic binaries, we care about:
   163→    // 1. Imported symbols (from .dynsym with UND section)
   164→    // 2. PLT entries that reference them
   165→
   166→    // Build a map of PLT entries to function names
   167→    let plt_map = build_plt_map(elf)?;
   168→
   169→    // Get sizes from libc if path provided
   170→    let libc_sizes = if let Some(ref libc_path) = args.libc_path {
   171→        load_libc_sizes(libc_path)?
   172→    } else {
   173→        HashMap::new()
   174→    };
   175→
   176→    // Collect imported libc functions
   177→    for sym in &elf.dynsyms {
   178→        if sym.st_type() == goblin::elf::sym::STT_FUNC {
   179→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   180→
   181→            // Check if it's a GLIBC symbol
   182→            let is_glibc = elf.dynstrtab.to_vec()?.iter()
   183→                .any(|s| s.contains("GLIBC"));
   184→
   185→            if !args.all && !is_glibc && sym.st_shndx != goblin::elf::section_header::SHN_UNDEF as usize {
   186→                continue;
   187→            }
   188→
   189→            if sym.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize {
   190→                // Skip if filtering and doesn't match
   191→                if let Some(ref filter) = args.filter {
   192→                    if !name.contains(filter) {
   193→                        continue;
   194→                    }
   195→                }
   196→
   197→                // Find PLT address for this symbol
   198→                let plt_addr = plt_map.get(name).copied();
   199→
   200→                let size = libc_sizes.get(name).copied().unwrap_or(0);
   201→
   202→                if let Some(addr) = plt_addr {
   203→                    functions.insert(addr, FunctionInfo {
   204→                        name: name.to_string(),
   205→                        size,
   206→                        address: addr,
   207→                        references: 0,
   208→                        source: Some("glibc".to_string()),
   209→                    });
   210→                }
   211→            }
   212→        }
   213→    }
   214→
   215→    // Count references to PLT stubs
   216→    count_references(args, elf, binary_data, &mut functions)?;
   217→
   218→    let mut func_vec: Vec<_> = functions.into_values().collect();
   219→    filter_and_sort(&args, &mut func_vec);
   220→
   221→    let total_code_size = func_vec.iter().map(|f| f.size).sum();
   222→
   223→    Ok(AnalysisResult {
   224→        binary_path: args.binary.display().to_string(),
   225→        is_dynamic: true,
   226→        total_functions: func_vec.len(),
   227→        total_code_size,
   228→        functions: func_vec,
   229→    })
   230→}
   231→
   232→/// Build a map of function names to their PLT addresses
   233→fn build_plt_map(elf: &Elf) -> Result<HashMap<String, u64>> {
   234→    let mut plt_map = HashMap::new();
   235→
   236→    // Find .rela.plt section for PLT relocations
   237→    for reloc in &elf.pltrelocs {
   238→        let sym_idx = reloc.r_sym;
   239→        if sym_idx < elf.dynsyms.len() {
   240→            let sym = &elf.dynsyms[sym_idx];
   241→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   242→
   243→            // PLT entry address: typically the relocation target + PLT base
   244→            // This is simplified; real PLT layout varies
   245→            if let Some(plt_shdr) = elf.section_headers.iter()
   246→                .find(|sh| {
   247→                    elf.shdr_strtab.get_at(sh.sh_name).unwrap_or("") == ".plt"
   248→                })
   249→            {
   250→                // Each PLT entry is typically 16 bytes on x86_64
   251→                // First entry is resolver, real entries start at +16
   252→                let plt_entry_addr = plt_shdr.sh_addr + 16 + (plt_map.len() as u64 * 16);
   253→                plt_map.insert(name.to_string(), plt_entry_addr);
   254→            }
   255→        }
   256→    }
   257→
   258→    Ok(plt_map)
   259→}
   260→
   261→/// Load function sizes from a glibc shared library
   262→fn load_libc_sizes(libc_path: &PathBuf) -> Result<HashMap<String, u64>> {
   263→    let data = fs::read(libc_path)
   264→        .with_context(|| format!("Failed to read libc: {:?}", libc_path))?;
   265→
   266→    let elf = Elf::parse(&data)?;
   267→    let mut sizes = HashMap::new();
   268→
   269→    for sym in &elf.dynsyms {
   270→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   271→            let name = elf.dynstrtab.get_at(sym.st_name).unwrap_or("???");
   272→            sizes.insert(name.to_string(), sym.st_size);
   273→        }
   274→    }
   275→
   276→    // Also check regular symtab if available
   277→    for sym in &elf.syms {
   278→        if sym.st_type() == goblin::elf::sym::STT_FUNC && sym.st_size > 0 {
   279→            let name = elf.strtab.get_at(sym.st_name).unwrap_or("???");
   280→            sizes.entry(name.to_string()).or_insert(sym.st_size);
   281→        }
   282→    }
   283→
   284→    Ok(sizes)
   285→}
   286→
   287→/// Count call references to functions using disassembly
   288→fn count_references(
   289→    args: &Args,
   290→    elf: &Elf,
   291→    binary_data: &[u8],
   292→    functions: &mut HashMap<u64, FunctionInfo>,
   293→) -> Result<()> {
   294→    let cs = Capstone::new()
   295→        .x86()
   296→        .mode(arch::x86::ArchMode::Mode64)
   297→        .syntax(arch::x86::ArchSyntax::Att)
   298→        .detail(true)
   299→        .build()
   300→        .map_err(|e| anyhow::anyhow!("Failed to create Capstone: {}", e))?;
   301→
   302→    // Find executable sections
   303→    for shdr in &elf.section_headers {
   304→        // Check if section is executable (SHF_EXECINSTR = 0x4)
   305→        if shdr.sh_flags & 0x4 == 0 {
   306→            continue;
   307→        }
   308→
   309→        let section_name = elf.shdr_strtab.get_at(shdr.sh_name).unwrap_or("");
   310→
   311→        // Skip PLT itself to avoid double-counting
   312→        if section_name == ".plt" || section_name == ".plt.got" {
   313→            continue;
   314→        }
   315→
   316→        let start = shdr.sh_offset as usize;
   317→        let end = start + shdr.sh_size as usize;
   318→
   319→        if end > binary_data.len() {
   320→            continue;
   321→        }
   322→
   323→        let section_data = &binary_data[start..end];
   324→        let section_addr = shdr.sh_addr;
   325→
   326→        let insns = cs.disasm_all(section_data, section_addr)
   327→            .map_err(|e| anyhow::anyhow!("Disassembly failed: {}", e))?;
   328→
   329→        for insn in insns.iter() {
   330→            let mnemonic = insn.mnemonic().unwrap_or("");
   331→
   332→            // Look for call and jmp instructions
   333→            if mnemonic == "call" || mnemonic == "callq" {
   334→                if let Some(target) = extract_call_target(&insn) {
   335→                    if let Some(func) = functions.get_mut(&target) {
   336→                        func.references += 1;
   337→                        if args.verbose {
   338→                            eprintln!(
   339→                                "  0x{:x}: {} -> {} (0x{:x})",
   340→                                insn.address(),
   341→                                mnemonic,
   342→                                func.name,
   343→                                target
   344→                            );
   345→                        }
   346→                    }
   347→                }
   348→            }
   349→        }
   350→    }
   351→
   352→    Ok(())
   353→}
   354→
   355→/// Extract the target address from a call instruction
   356→fn extract_call_target(insn: &capstone::Insn) -> Option<u64> {
   357→    let op_str = insn.op_str()?;
   358→
   359→    // Direct call: "0x1234" or "symbol"
   360→    // We need the absolute address
   361→
   362→    // For relative calls, capstone gives us the computed target
   363→    // Check if it's a hex address
   364→    if op_str.starts_with("0x") || op_str.starts_with("0X") {
   365→        u64::from_str_radix(&op_str[2..], 16).ok()
   366→    } else if let Ok(addr) = op_str.parse::<u64>() {
   367→        Some(addr)
   368→    } else {
   369→        // For PC-relative calls, we need to compute the target
   370→        // Format might be like "0x401234" after capstone processes it
   371→        // or it might be an indirect call like "*%rax" which we skip
   372→        if op_str.starts_with('*') {
   373→            None // indirect call
   374→        } else {
   375→            // Try parsing as hex without prefix
   376→            u64::from_str_radix(op_str.trim(), 16).ok()
   377→        }
   378→    }
   379→}
   380→
   381→/// Check if a symbol is internal (compiler/runtime generated)
   382→fn is_internal_symbol(name: &str) -> bool {
   383→    // Skip internal symbols unless user wants all
   384→    name.starts_with("_ZN") || // Rust mangled
   385→    name.starts_with("__rust") ||
   386→    name.starts_with(".L") ||
   387→    name.starts_with("GCC_except") ||
   388→    name.starts_with("__gcc") ||
   389→    name.starts_with("_GLOBAL") ||
   390→    name.contains("cgu") || // codegen unit
   391→    name == "_start" ||
   392→    name == "__libc_csu_init" ||
   393→    name == "__libc_csu_fini"
   394→}
   395→
   396→fn filter_and_sort(args: &Args, functions: &mut Vec<FunctionInfo>) {
   397→    // Filter by min refs
   398→    functions.retain(|f| f.references >= args.min_refs);
   399→
   400→    // Sort
   401→    match args.sort {
   402→        SortBy::Name => functions.sort_by(|a, b| a.name.cmp(&b.name)),
   403→        SortBy::Size => functions.sort_by(|a, b| b.size.cmp(&a.size)),
   404→        SortBy::Refs => functions.sort_by(|a, b| b.references.cmp(&a.references)),
   405→    }
   406→}
   407→
   408→fn output_result(args: &Args, result: &AnalysisResult) -> Result<()> {
   409→    match args.format {
   410→        OutputFormat::Json => {
   411→            println!("{}", serde_json::to_string_pretty(result)?);
   412→        }
   413→        OutputFormat::Csv => {
   414→            println!("name,size,address,references,source");
   415→            for f in &result.functions {
   416→                println!(
   417→                    "{},{},{:#x},{},{}",
   418→                    f.name,
   419→                    f.size,
   420→                    f.address,
   421→                    f.references,
   422→                    f.source.as_deref().unwrap_or("")
   423→                );
   424→            }
   425→        }
   426→        OutputFormat::Table => {
   427→            println!("Binary: {}", result.binary_path);
   428→            println!("Type: {}", if result.is_dynamic { "dynamic" } else { "static" });
   429→            println!("Functions: {}", result.total_functions);
   430→            println!("Total code size: {} bytes", result.total_code_size);
   431→            println!();
   432→            println!("{:<40} {:>10} {:>12} {:>8}", "FUNCTION", "SIZE", "ADDRESS", "REFS");
   433→            println!("{}", "-".repeat(74));
   434→
   435→            for f in &result.functions {
   436→                println!(
   437→                    "{:<40} {:>10} {:#12x} {:>8}",
   438→                    truncate(&f.name, 40),
   439→                    f.size,
   440→                    f.address,
   441→                    f.references
   442→                );
   443→            }
   444→        }
   445→    }
   446→
   447→    Ok(())
   448→}
   449→
   450→fn truncate(s: &str, max_len: usize) -> String {
   451→    if s.len() <= max_len {
   452→        s.to_string()
   453→    } else {
   454→        format!("{}...", &s[..max_len - 3])
   455→    }
   456→}
   457→

