//! and counts references through PLT stubs.

use anyhow::{Context, Result};
use capstone::prelude::*;
use clap::{Parser, ValueEnum};
use goblin::elf::Elf;
use is_libc_used::is_libc_used_from_bytes;
use serde::Serialize;
use std::collections::HashMap;
use std::fs;
