                .any(|s| s.contains("GLIBC"));

            if !args.all && !is_glibc && sym.st_shndx != goblin::elf::section_header::SHN_UNDEF as usize {
                continue;
            }

            if sym.st_shndx == goblin::elf::section_header::SHN_UNDEF as usize {
                // Skip if filtering and doesn't match
